import { normalizeUuid } from '../utils/uuid.js';
import { exec } from 'node:child_process';
import { copyFile, mkdir, readFile, stat, writeFile } from 'node:fs/promises';
import { dirname, isAbsolute, resolve, sep, posix } from 'node:path';
import { promisify } from 'node:util';

import { getChangesInRepo, getGitDiff, type GitChange, type GitDiff } from '../git/index.js';
import { AgentContext } from '../context/agent-context.js';
import { skillSchema, type Skill } from '../skills/index.js';

import { observabilityHeadersFromEnv, type ObservabilityRuntime } from '../observability/index.js';
import { WorkspaceCompletion, type CompletionCallbackRuntime } from './completion-callback.js';
export type { CompletionCallbackRuntime, WorkspaceCompletionRegistration } from './completion-callback.js';

const execAsync = promisify(exec);
type FetchRequestInit = NonNullable<Parameters<typeof fetch>[1]> & { readonly timeoutMs?: number };


export type TargetType = 'binary' | 'binary-minimal' | 'source' | 'source-minimal' | 'base-image-minimal' | 'base-image' | 'builder';
export type PlatformType = 'linux/amd64' | 'linux/arm64';
export type GitProvider = 'github' | 'gitlab' | 'bitbucket';

export interface WorkspaceCommandResult {
  readonly command: string;
  readonly exitCode: number;
  readonly stdout: string;
  readonly stderr: string;
  readonly timeoutOccurred: boolean;
}

export interface FileOperationResult {
  readonly success: boolean;
  readonly sourcePath: string;
  readonly destinationPath: string;
  readonly fileSize?: number;
  readonly error?: string;
}

export interface BaseWorkspace {
  readonly workingDir: string;
  executeCommand(command: string, options?: { readonly cwd?: string | null; readonly timeoutSeconds?: number }): Promise<WorkspaceCommandResult>;
  fileUpload(sourcePath: string, destinationPath: string): Promise<FileOperationResult>;
  fileDownload(sourcePath: string, destinationPath: string): Promise<FileOperationResult>;
  gitChanges(path: string): Promise<GitChange[]>;
  gitDiff(path: string): Promise<GitDiff>;
  pause(): Promise<void>;
  resume(): Promise<void>;
}

export interface LocalWorkspaceOptions {
  readonly completionCallback?: CompletionCallbackRuntime;
  readonly observability?: ObservabilityRuntime;
  readonly workingDir?: string;
  readonly working_dir?: string;
}

export class LocalWorkspace implements BaseWorkspace {
  readonly workingDir: string;
  private readonly completion: WorkspaceCompletion;

  constructor(options: LocalWorkspaceOptions = {}) {
    this.completion = new WorkspaceCompletion(options.completionCallback);
    this.workingDir = resolve(options.workingDir ?? options.working_dir ?? 'workspace/project');
  }

  registerConversation(id: string): void { this.completion.registerConversation(id); }
  registerCost(cost: number | null): void { this.completion.registerCost(cost); }
  get accumulatedCost(): number | null { return this.completion.accumulatedCost; }
  async close(error?: unknown): Promise<void> { await this.completion.close(error); }

  async executeCommand(command: string, options: { readonly cwd?: string | null; readonly timeoutSeconds?: number } = {}): Promise<WorkspaceCommandResult> {
    const cwd = options.cwd === undefined || options.cwd === null ? this.workingDir : this.resolvePath(options.cwd);
    const timeout = (options.timeoutSeconds ?? 30) * 1000;
    try {
      const { stdout, stderr } = await execAsync(command, { cwd, timeout });
      return { command, exitCode: 0, stdout, stderr, timeoutOccurred: false };
    } catch (error) {
      if (isExecError(error)) {
        return {
          command,
          exitCode: typeof error.code === 'number' ? error.code : -1,
          stdout: error.stdout ?? '',
          stderr: error.stderr ?? '',
          timeoutOccurred: error.killed === true || error.signal === 'SIGTERM',
        };
      }
      throw error;
    }
  }

  async fileUpload(sourcePath: string, destinationPath: string): Promise<FileOperationResult> {
    return this.copy(sourcePath, destinationPath);
  }

  async fileDownload(sourcePath: string, destinationPath: string): Promise<FileOperationResult> {
    return this.copy(sourcePath, destinationPath);
  }

  async gitChanges(path: string): Promise<GitChange[]> {
    return getChangesInRepo(this.resolvePath(path), 'HEAD');
  }

  async gitDiff(path: string): Promise<GitDiff> {
    return getGitDiff(this.resolvePath(path), 'HEAD');
  }

  async pause(): Promise<void> {
    return Promise.resolve();
  }

  async resume(): Promise<void> {
    return Promise.resolve();
  }

  private async copy(sourcePath: string, destinationPath: string): Promise<FileOperationResult> {
    const source = this.resolvePath(sourcePath);
    const destination = this.resolvePath(destinationPath);
    try {
      await mkdir(dirname(destination), { recursive: true });
      await copyFile(source, destination);
      const info = await stat(destination);
      return { success: true, sourcePath: source, destinationPath: destination, fileSize: info.size };
    } catch (error) {
      return { success: false, sourcePath: source, destinationPath: destination, error: error instanceof Error ? error.message : String(error) };
    }
  }

  private resolvePath(path: string): string {
    return isAbsolute(path) ? resolve(path) : resolve(this.workingDir, path);
  }
}

export interface RemoteWorkspaceOptions extends LocalWorkspaceOptions {
  readonly host: string;
  readonly apiKey?: string | null;
  readonly api_key?: string | null;
  readonly readTimeoutSeconds?: number;
  readonly read_timeout?: number;
  readonly runtimeConversationId?: string | null;
  readonly runtime_conversation_id?: string | null;
}

export interface RemoteSkillLoadOptions {
  readonly projectDirs?: readonly string[];
  readonly loadPublic?: boolean;
  readonly loadUser?: boolean;
  readonly loadProject?: boolean;
  readonly loadOrg?: boolean;
  readonly timeoutSeconds?: number;
  readonly baseContext?: AgentContext | null;
}

export class RemoteWorkspace implements BaseWorkspace {
  private readonly completion: WorkspaceCompletion;
  private readonly observability: ObservabilityRuntime;
  readonly host: string;
  readonly apiKey: string | null;
  readonly workingDir: string;
  readonly readTimeoutSeconds: number;
  readonly runtimeConversationId: string | null;

  constructor(options: RemoteWorkspaceOptions) {
    this.completion = new WorkspaceCompletion(options.completionCallback);
    this.observability = options.observability ?? {};
    this.host = options.host.replace(/\/+$/u, '');
    this.apiKey = options.apiKey ?? options.api_key ?? null;
    this.workingDir = remotePath(options.workingDir ?? options.working_dir ?? 'workspace/project');
    this.readTimeoutSeconds = options.readTimeoutSeconds ?? options.read_timeout ?? 600;
    this.runtimeConversationId = normalizeRuntimeConversationId(options.runtimeConversationId ?? options.runtime_conversation_id ?? null);
  }

  registerConversation(id: string): void { this.completion.registerConversation(id); }
  registerCost(cost: number | null): void { this.completion.registerCost(cost); }
  get accumulatedCost(): number | null { return this.completion.accumulatedCost; }
  async close(error?: unknown): Promise<void> { await this.completion.close(error); }

  async alive(): Promise<boolean> {
    try {
      const response = await fetch(`${this.host}/health`, { signal: AbortSignal.timeout(5_000) });
      return response.ok;
    } catch {
      return false;
    }
  }

  async getServerInfo(): Promise<Record<string, unknown>> {
    const response = await this.request('/server_info');
    const data = await response.json();
    return isRecord(data) ? data : {};
  }

  /**
   * Load server skills, replacing the base context's skills while preserving its
   * other fields and applying its disabledSkills deny-list. Later project
   * directories override earlier skills with the same name.
   *
   * Local automatic public/user discovery is not implemented. When the server
   * returns no usable skills (including on failure), retain the supplied context's
   * explicit skills instead of Python's automatic public-skill fallback.
   */
  async loadSkillsFromAgentServer(options: RemoteSkillLoadOptions = {}): Promise<[Skill[], AgentContext]> {
    if (!this.host || this.host === 'undefined') {
      throw new Error('Workspace not initialized. Start the workspace before loading skills.');
    }
    const flags = {
      load_public: options.loadPublic ?? true,
      load_user: options.loadUser ?? true,
      load_project: options.loadProject ?? true,
      load_org: options.loadOrg ?? true,
    };
    const byName = new Map<string, Record<string, unknown>>();
    const load = async (projectDir: string, selection: typeof flags): Promise<void> => {
      const skills = await this.callSkillsApi({ ...selection, project_dir: projectDir, sandbox_config: null }, options.timeoutSeconds ?? 60);
      for (const skill of skills) {
        if (isRecord(skill)) {
          const name = skill.name === undefined ? 'unknown' : skill.name;
          if (typeof name === 'string') byName.set(name, skill);
        }
      }
    };
    if (options.projectDirs?.length) {
      await load(this.workingDir, { ...flags, load_project: false });
      if (flags.load_project) {
        for (const directory of options.projectDirs) {
          await load(directory, { load_public: false, load_user: false, load_project: true, load_org: false });
        }
      }
    } else {
      await load(this.workingDir, flags);
    }
    const loaded: Skill[] = [];
    for (const data of byName.values()) {
      const triggers = data.triggers ?? [];
      if (!Array.isArray(triggers)) continue;
      const trigger = Array.isArray(triggers) && triggers.length > 0
        ? triggers.some((value) => typeof value === 'string' && value.startsWith('/'))
          ? { type: 'task', triggers }
          : { type: 'keyword', keywords: triggers }
        : null;
      const result = skillSchema.safeParse({
        name: data.name === undefined ? 'unknown' : data.name,
        content: data.content === undefined ? '' : data.content, trigger,
        source: data.source, description: data.description,
        isAgentskillsFormat: data.is_agentskills_format,
        disableModelInvocation: data.disable_model_invocation,
      });
      if (result.success) loaded.push(result.data);
    }
    const base = options.baseContext ?? new AgentContext();
    return [loaded, new AgentContext({ ...base, skills: loaded.length > 0 ? loaded : base.skills })];
  }

  private async callSkillsApi(payload: Record<string, unknown>, timeoutSeconds: number): Promise<unknown[]> {
    const serverErrors = new Set(Array.from({ length: 100 }, (_, index) => 500 + index));
    for (let attempt = 0; attempt < 3; attempt += 1) {
      try {
        const response = await this.request('/api/skills', {
          method: 'POST', headers: { 'content-type': 'application/json' },
          body: JSON.stringify(payload), timeoutMs: timeoutSeconds * 1000,
        }, serverErrors);
        if (response.ok) {
          const data: unknown = await response.json();
          return isRecord(data) && Array.isArray(data.skills) ? data.skills as unknown[] : [];
        }
        await response.body?.cancel();
      } catch (error) {
        const transient = error instanceof TypeError
          || (error instanceof Error && ['TimeoutError', 'AbortError'].includes(error.name));
        if (!transient) return [];
      }
      if (attempt < 2) await delay(1000 * 2 ** attempt);
    }
    return [];
  }

  async executeCommand(command: string, options: { readonly cwd?: string | null; readonly timeoutSeconds?: number } = {}): Promise<WorkspaceCommandResult> {
    const timeoutSeconds = options.timeoutSeconds ?? 30;
    const payload: Record<string, unknown> = { command, timeout: Math.trunc(timeoutSeconds) };
    payload.cwd = options.cwd === undefined || options.cwd === null ? this.workingDir : joinRemotePath(this.workingDir, options.cwd);

    try {
      const start = await this.request(`${this.apiPrefix}/bash/start_bash_command`, {
        method: 'POST',
        body: JSON.stringify(payload),
        headers: { 'content-type': 'application/json' },
        timeoutMs: (timeoutSeconds + 5) * 1000,
      });
      const commandId = this.parseCommandId(await start.json());

      const stdoutParts: string[] = [];
      const stderrParts: string[] = [];
      const seen = new Set<string>();
      let exitCode: number | null = null;
      let lastOrder = -1;
      const deadline = Date.now() + timeoutSeconds * 1000;

      while (Date.now() < deadline) {
        const params = new URLSearchParams({ command_id__eq: commandId, sort_order: 'TIMESTAMP', limit: '100', kind__eq: 'BashOutput' });
        if (lastOrder >= 0) {
          params.set('order__gt', String(lastOrder));
        }
        const response = await this.request(`${this.apiPrefix}/bash/bash_events/search?${params.toString()}`, { timeoutMs: this.readTimeoutSeconds * 1000 });
        const result = (await response.json()) as { items?: Array<Record<string, unknown>> };
        for (const event of result.items ?? []) {
          if (event.kind !== 'BashOutput') {
            continue;
          }
          if (typeof event.id === 'string') {
            if (seen.has(event.id)) {
              throw new Error(`Duplicate bash event received: ${event.id}`);
            }
            seen.add(event.id);
          }
          if (typeof event.order === 'number' && event.order > lastOrder) {
            lastOrder = event.order;
          }
          if (typeof event.stdout === 'string') {
            stdoutParts.push(event.stdout);
          }
          if (typeof event.stderr === 'string') {
            stderrParts.push(event.stderr);
          }
          if (typeof event.exit_code === 'number') {
            exitCode = event.exit_code;
          }
        }
        if (exitCode !== null) {
          break;
        }
        await delay(100);
      }

      if (exitCode === null) {
        exitCode = -1;
        stderrParts.push(`Command timed out after ${timeoutSeconds} seconds`);
      }
      const stderr = stderrParts.join('');
      return { command, exitCode, stdout: stdoutParts.join(''), stderr, timeoutOccurred: exitCode === -1 && stderr.includes('timed out') };
    } catch (error) {
      return { command, exitCode: -1, stdout: '', stderr: `Remote execution error: ${error instanceof Error ? error.message : String(error)}`, timeoutOccurred: false };
    }
  }

  async startCommand(command: string, options: { readonly cwd?: string | null; readonly timeoutSeconds?: number } = {}): Promise<string> {
    const timeoutSeconds = options.timeoutSeconds ?? 30;
    const payload: Record<string, unknown> = { command, timeout: Math.trunc(timeoutSeconds) };
    if (options.cwd !== undefined && options.cwd !== null) {
      payload.cwd = joinRemotePath(this.workingDir, options.cwd);
    }
    const start = await this.request(`${this.apiPrefix}/bash/start_bash_command`, {
      method: 'POST',
      body: JSON.stringify(payload),
      headers: { 'content-type': 'application/json' },
      timeoutMs: (timeoutSeconds + 5) * 1000,
    });
    return this.parseCommandId(await start.json());
  }

  async getCommandOutput(commandId?: string | null): Promise<Record<string, unknown> | null> {
    const params = new URLSearchParams({ kind__eq: 'BashOutput', sort_order: 'TIMESTAMP_DESC', limit: '1' });
    if (commandId !== undefined && commandId !== null) {
      params.set('command_id__eq', commandId);
    }
    const response = await this.request(`${this.apiPrefix}/bash/bash_events/search?${params.toString()}`, { timeoutMs: 60_000 });
    const page = (await response.json()) as { items?: Array<Record<string, unknown>> };
    return page.items?.[0] ?? null;
  }

  async getRuntimeSessionKey(): Promise<string> {
    this.requireRuntimeScope();
    const response = await this.request(`${this.apiPrefix}/runtime/credentials`, { method: 'POST', timeoutMs: 60_000 });
    const data = (await response.json()) as { session_api_key?: unknown };
    if (typeof data.session_api_key !== 'string' || data.session_api_key.length === 0) {
      throw new Error('agent-server returned an empty session credential');
    }
    return data.session_api_key;
  }

  /** Stop only this managed command; already-finished and unknown IDs are no-ops. */
  async stopCommand(commandId: string): Promise<void> {
    const response = await this.request(`${this.apiPrefix}/bash/bash_commands/${encodeURIComponent(commandId)}/stop`,
      { method: 'POST', timeoutMs: 60_000 }, new Set([404]));
    await response.body?.cancel();
  }

  async releaseRuntime(): Promise<void> {
    this.requireRuntimeScope();
    // A 404 means the runtime was already released; that is not an error.
    await this.request(`${this.apiPrefix}/runtime`, { method: 'DELETE', timeoutMs: 60_000 }, new Set([404]));
  }

  async fileUpload(sourcePath: string | Uint8Array, destinationPath: string): Promise<FileOperationResult> {
    const source = sourcePath instanceof Uint8Array ? 'upload' : resolve(sourcePath);
    const destination = joinRemotePath(this.workingDir, destinationPath);
    try {
      let content: Buffer;
      let filename: string;
      if (sourcePath instanceof Uint8Array) {
        content = Buffer.from(sourcePath);
        filename = 'upload';
      } else {
        content = await readFile(source);
        filename = source.split(/[\\/]/u).at(-1) ?? 'file';
      }
      const form = new FormData();
      form.set('file', new Blob([content]), filename);
      const params = new URLSearchParams({ path: destination });
      const response = await this.request(`${this.apiPrefix}/file/upload?${params.toString()}`, { method: 'POST', body: form, timeoutMs: 60_000 });
      const data = (await response.json().catch(() => ({}))) as Record<string, unknown>;
      const result: FileOperationResult = { success: data.success !== false, sourcePath: source, destinationPath: destination, fileSize: typeof data.file_size === 'number' ? data.file_size : content.length };
      if (typeof data.error === 'string') {
        return { ...result, error: data.error };
      }
      return result;
    } catch (error) {
      return { success: false, sourcePath: source, destinationPath: destination, error: error instanceof Error ? error.message : String(error) };
    }
  }

  async fileDownload(sourcePath: string, destinationPath: string): Promise<FileOperationResult> {
    const source = joinRemotePath(this.workingDir, sourcePath);
    const destination = resolve(destinationPath);
    try {
      const params = new URLSearchParams({ path: source });
      const response = await this.request(`${this.apiPrefix}/file/download?${params.toString()}`, { timeoutMs: 60_000 });
      const content = Buffer.from(await response.arrayBuffer());
      await mkdir(dirname(destination), { recursive: true });
      await writeFile(destination, content);
      return { success: true, sourcePath: source, destinationPath: destination, fileSize: content.length };
    } catch (error) {
      return { success: false, sourcePath: source, destinationPath: destination, error: error instanceof Error ? error.message : String(error) };
    }
  }

  async gitChanges(path: string): Promise<GitChange[]> {
    const params = new URLSearchParams({ path: joinRemotePath(this.workingDir, path), ref: 'HEAD' });
    const response = await this.request(`${this.apiPrefix}/git/changes?${params.toString()}`, { timeoutMs: 60_000 });
    return ((await response.json()) as GitChange[]).sort((left, right) => left.path.localeCompare(right.path));
  }

  async gitDiff(path: string): Promise<GitDiff> {
    const params = new URLSearchParams({ path: joinRemotePath(this.workingDir, path), ref: 'HEAD' });
    const response = await this.request(`${this.apiPrefix}/git/diff?${params.toString()}`, { timeoutMs: 60_000 });
    return (await response.json()) as GitDiff;
  }

  async pause(): Promise<void> {
    return Promise.resolve();
  }

  async resume(): Promise<void> {
    return Promise.resolve();
  }

  private get apiPrefix(): string {
    if (this.runtimeConversationId === null) {
      return '/api';
    }
    return `/api/conversations/${encodeURIComponent(this.runtimeConversationId)}`;
  }

  private requireRuntimeScope(): void {
    if (this.runtimeConversationId === null) {
      throw new Error('Runtime lifecycle requires a conversation scope');
    }
  }

  private parseCommandId(data: unknown): string {
    const id = isRecord(data) ? data.id : undefined;
    if (typeof id !== 'string' || id.length === 0) {
      throw new Error('agent-server did not return a bash command id');
    }
    return id;
  }

  private async request(path: string, init: FetchRequestInit = {}, acceptableStatusCodes: ReadonlySet<number> = new Set()): Promise<Response> {
    const headers = new Headers(observabilityHeadersFromEnv(this.observability.env, this.observability.injectHeaders));
    new Headers(init.headers).forEach((value, name) => headers.set(name, value));
    if (this.apiKey !== null) {
      headers.set('X-Session-API-Key', this.apiKey);
    }
    const response = await fetch(path.startsWith('http') ? path : `${this.host}${path}`, {
      ...init,
      headers,
      signal: init.signal ?? AbortSignal.timeout(init.timeoutMs ?? this.readTimeoutSeconds * 1000),
    });
    if (!response.ok && !acceptableStatusCodes.has(response.status)) {
      throw new Error(`agent-server request failed: ${response.status} ${response.statusText} ${await response.text().catch(() => '')}`.trim());
    }
    return response;
  }
}

export interface WorkspaceOptions extends LocalWorkspaceOptions {
  readonly host?: string | null;
  readonly apiKey?: string | null;
  readonly api_key?: string | null;
  readonly readTimeoutSeconds?: number;
  readonly read_timeout?: number;
  readonly runtimeConversationId?: string | null;
  readonly runtime_conversation_id?: string | null;
}

export function workspace(options: WorkspaceOptions = {}): BaseWorkspace {
  if (options.host !== undefined && options.host !== null && options.host.length > 0) {
    return new RemoteWorkspace({ ...options, host: options.host });
  }
  return new LocalWorkspace(options);
}

export interface RepoSourceOptions {
  readonly url: string;
  readonly ref?: string | null;
  readonly provider?: GitProvider | null;
}

export class RepoSource {
  readonly url: string;
  readonly ref: string | null;
  readonly provider: GitProvider | null;

  constructor(options: string | RepoSourceOptions) {
    const source = typeof options === 'string' ? { url: options } : options;
    this.url = validateUrl(source.url);
    this.ref = source.ref ?? null;
    this.provider = source.provider ?? null;
    if (isShortUrlFormat(this.url) && this.provider === null) {
      throw new Error(`Short URL format '${this.url}' requires explicit provider field`);
    }
  }

  getProvider(): GitProvider {
    if (this.provider !== null) {
      return this.provider;
    }
    const detected = detectProviderFromUrl(this.url);
    if (detected !== null) {
      return detected;
    }
    throw new Error(`Cannot determine provider for URL: ${this.url}`);
  }

  getTokenName(): string {
    return providerTokenNames[this.getProvider()];
  }
}

export interface RepoMapping {
  readonly url: string;
  readonly dirName: string;
  readonly localPath: string;
  readonly ref?: string | null;
}

export interface CloneResult {
  readonly successCount: number;
  readonly failedRepos: readonly string[];
  readonly repoMappings: Readonly<Record<string, RepoMapping>>;
}

const providerTokenNames: Record<GitProvider, string> = {
  github: 'github_token',
  gitlab: 'gitlab_token',
  bitbucket: 'bitbucket_token',
};

const providerHosts: Record<GitProvider, string> = {
  github: 'github.com',
  gitlab: 'gitlab.com',
  bitbucket: 'bitbucket.org',
};

const providerTokenFormat: Record<GitProvider, (token: string) => string> = {
  github: (token) => `${token}@`,
  gitlab: (token) => `oauth2:${token}@`,
  bitbucket: (token) => `x-token-auth:${token}@`,
};

export function buildCloneUrl(url: string, provider: GitProvider, token: string | null = null, explicitProvider = false): string {
  const host = providerHosts[provider];
  const auth = token === null ? '' : providerTokenFormat[provider](token);
  if (isShortUrlFormat(url)) {
    return `https://${auth}${host}/${url}.git`;
  }
  if (token === null) {
    return url;
  }

  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return url;
  }
  const hostname = parsed.hostname.toLowerCase();
  if (parsed.protocol !== 'https:' || parsed.username !== '' || hostname.length === 0) {
    return url;
  }
  if (hostname !== host) {
    // An auto-detected provider derives from the URL, so it cannot authorize
    // another host — and never a lookalike of the public one.
    if (!explicitProvider || hostname.startsWith(`${host}.`)) {
      return url;
    }
  }

  const netloc = parsed.port === '' ? hostname : `${hostname}:${parsed.port}`;
  return `https://${auth}${netloc}${parsed.pathname}${parsed.search}${parsed.hash}`;
}

export function getReposContext(repoMappings: Readonly<Record<string, RepoMapping>>): string {
  const entries = Object.entries(repoMappings);
  if (entries.length === 0) {
    return '';
  }
  const lines = ['## Cloned Repositories', '', 'The following repositories have been cloned to your workspace:', ''];
  for (const [url, mapping] of entries) {
    const ref = mapping.ref === undefined || mapping.ref === null ? '' : ` (ref: ${mapping.ref})`;
    lines.push(`- \`${mapping.url || url}\`${ref} → \`${mapping.localPath}/\``);
  }
  lines.push('');
  return lines.join('\n');
}

function validateUrl(value: string): string {
  if (/^[\w-]+\/[\w.-]+$/u.test(value)) {
    return value;
  }
  const normalized = value.startsWith('http://') ? `https://${value.slice(7)}` : value;
  if (normalized.startsWith('https://') || normalized.startsWith('git@') || normalized.startsWith('file://')) {
    return normalized;
  }
  throw new Error("URL must be 'owner/repo' format or a valid git URL (https://, git@, or file://)");
}

function isShortUrlFormat(url: string): boolean {
  return !url.includes('://') && !url.startsWith('git@');
}

function detectProviderFromUrl(url: string): GitProvider | null {
  if (url.startsWith('git@')) {
    const host = url.split('@')[1]?.split(':')[0]?.toLowerCase();
    return providerFromHost(host ?? '');
  }
  try {
    return providerFromHost(new URL(url).host.toLowerCase());
  } catch {
    return null;
  }
}

function providerFromHost(host: string): GitProvider | null {
  for (const [provider, providerHost] of Object.entries(providerHosts) as [GitProvider, string][]) {
    if (host === providerHost) {
      return provider;
    }
  }
  return null;
}

function remotePath(path: string): string {
  return path.split(sep).join(posix.sep);
}

function joinRemotePath(base: string, path: string): string {
  const pathStr = remotePath(path);
  if (pathStr.startsWith('/') || /^[a-zA-Z]:\//u.test(pathStr)) {
    return pathStr;
  }
  const baseStr = remotePath(base);
  const prefix = baseStr.startsWith('/') ? '/' : '';
  const parts = [...baseStr.split('/'), ...pathStr.split('/')].filter((part) => part.length > 0 && part !== '.');
  return `${prefix}${parts.join('/')}`;
}

async function delay(ms: number): Promise<void> {
  await new Promise((resolveDelay) => setTimeout(resolveDelay, ms));
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function normalizeRuntimeConversationId(value: string | null): string | null {
  if (value === null) {
    return null;
  }
  try {
    return normalizeUuid(value);
  } catch {
    throw new Error('runtimeConversationId must be a valid UUID or null');
  }
}

interface ExecError {
  readonly code?: number | string | null;
  readonly stdout?: string;
  readonly stderr?: string;
  readonly killed?: boolean;
  readonly signal?: string | null;
}

function isExecError(error: unknown): error is ExecError {
  return typeof error === 'object' && error !== null && ('stdout' in error || 'stderr' in error || 'code' in error);
}
