import { z } from 'zod';
import { foldDeprecatedToolSwitches, foldRetiredToolSwitches } from '../tool/defaults.js';
import { persistedToolSpecsSchema } from '../tool/spec-validation.js';

import { condenserSettingsSchema, hardCondenserSettingsSchema } from './condenser-settings.js';
import { metaProfileLlmsSchema, metaProfileSchema } from '../meta-profiles/index.js';
export * from './condenser-settings.js';

import {
  acpServerKindSchema,
  profileVerificationSettingsSchema,
  type ProfileVerificationSettings,
} from '../profiles/index.js';
export const RAW_LLM_FIELDS_IGNORED_WHEN_PROFILE_SELECTED = [
  'provider',
  'model',
  'openaiApiMode',
  'baseUrl',
  'apiVersion',
  'timeout',
  'temperature',
  'topP',
  'topK',
  'maxInputTokens',
  'maxOutputTokens',
  'reasoningEffort',
  'reasoningSummary',
  'promptCacheRetention',
  'promptCacheKey',
  'inputCostPerToken',
  'outputCostPerToken',
] as const;

export type RawLlmFieldIgnoredWhenProfileSelected = (typeof RAW_LLM_FIELDS_IGNORED_WHEN_PROFILE_SELECTED)[number];

export type ProfileSelectedLlmSettings = {
  readonly profileId?: string | null;
  readonly encrypted_reasoning?: string | null;
} & {
  readonly [K in RawLlmFieldIgnoredWhenProfileSelected]?: unknown;
};

export const AGENT_SETTINGS_SCHEMA_VERSION = 8;
export const CONVERSATION_SETTINGS_SCHEMA_VERSION = 1;

const settingsSchemaVersion = (version: number) => z.literal(version).default(version);

export const observabilityMetadataSchema = z.record(z.string().min(1), z.unknown());
export const observabilityTagsSchema = z.array(z.string());

const OBSERVABILITY_SPAN_NAME_PATTERN = /^[A-Za-z0-9._:/-]+$/u;
const OBSERVABILITY_SPAN_NAME_MAX_LENGTH = 128;

export const observabilitySpanNameSchema = z
  .string()
  .min(1, 'Observability span name must be a non-empty string')
  .max(OBSERVABILITY_SPAN_NAME_MAX_LENGTH, `Observability span name exceeds maximum length of ${OBSERVABILITY_SPAN_NAME_MAX_LENGTH} characters`)
  .regex(OBSERVABILITY_SPAN_NAME_PATTERN, 'Observability span name may only contain letters, numbers, dots, underscores, colons, slashes, and hyphens');

export const conversationSettingsSchema = z
  .object({
    schema_version: settingsSchemaVersion(CONVERSATION_SETTINGS_SCHEMA_VERSION),
    max_iterations: z.number().int().min(1).default(500),
    observability_metadata: observabilityMetadataSchema.nullable().default(null),
    observability_tags: observabilityTagsSchema.nullable().default(null),
    observability_span_name: observabilitySpanNameSchema.nullable().default(null),
  })
  .strict();

const agentSettingsBaseFields = {
  schema_version: settingsSchemaVersion(AGENT_SETTINGS_SCHEMA_VERSION),
  mcp_config: z.unknown().nullable().default(null),
} as const;

const defaultVerificationSettings: ProfileVerificationSettings = profileVerificationSettingsSchema.parse({});

const openHandsAgentSettingsObjectSchema = z
  .object({
    ...agentSettingsBaseFields,
    agent_kind: z.literal('openhands').default('openhands'),
    llm_profile_ref: z.string().min(1),
    agent: z.string().default('CodeActAgent'),
    tools: persistedToolSpecsSchema.nullable().default(null),
    persona: z.string().min(1).max(65536).nullable().default(null),
    enable_classify_and_switch_llm_tool: z.boolean().default(false),
    active_meta_profile: z.string().nullable().default(null),
    meta_profile: metaProfileSchema.nullable().default(null),
    meta_profile_llms: metaProfileLlmsSchema.default({}),
    tool_concurrency_limit: z.number().int().min(1).default(1),
    condenser: condenserSettingsSchema.prefault({}),
    hard_condenser: hardCondenserSettingsSchema.nullable().optional(),
    verification: profileVerificationSettingsSchema.default(defaultVerificationSettings),
  })
  .strict()
  .superRefine((settings, context) => {
    if (settings.hard_condenser !== undefined && settings.hard_condenser !== null
      && (settings.condenser.condenser_kind !== 'agent_reset' || !settings.condenser.enabled)) {
      context.addIssue({
        code: 'custom',
        path: ['hard_condenser'],
        message: 'hard_condenser requires an enabled agent_reset condenser',
      });
    }
  });

export const openHandsAgentSettingsSchema = z.preprocess(foldDeprecatedToolSwitches, openHandsAgentSettingsObjectSchema);

const acpAgentSettingsObjectSchema = z
  .object({
    ...agentSettingsBaseFields,
    agent_kind: z.literal('acp').default('acp'),
    acp_server: acpServerKindSchema.default('claude-code'),
    acp_command: z.array(z.string()).default([]),
    acp_args: z.array(z.string()).default([]),
    acp_model: z.string().nullable().default(null),
    acp_session_mode: z.string().nullable().default(null),
    acp_prompt_timeout: z.number().positive().default(1800),
    acp_startup_timeout: z.number().positive().default(90),
  })
  .strict();

export const acpAgentSettingsSchema = z.preprocess(data => {
  if (!isRecord(data)) return data;
  const payload = { ...data };
  if ('llm' in payload) process.emitWarning('ACPAgentSettings.llm is deprecated and ignored; ACP manages its own LLM.', { type: 'DeprecationWarning', code: 'OPENHANDS_ACP_LLM_IGNORED' });
  delete payload.llm;
  delete payload.enable_sub_agents;
  delete payload.enable_switch_llm_tool;
  return payload;
}, acpAgentSettingsObjectSchema);

export const agentSettingsSchema = z.union([openHandsAgentSettingsSchema, acpAgentSettingsSchema]);

export type ConversationSettings = z.infer<typeof conversationSettingsSchema>;
export type OpenHandsAgentSettings = z.infer<typeof openHandsAgentSettingsSchema>;
export type ACPAgentSettings = z.infer<typeof acpAgentSettingsSchema>;
export type AgentSettings = OpenHandsAgentSettings | ACPAgentSettings;

export function clearRawLlmFieldsWhenProfileSelected<T extends ProfileSelectedLlmSettings>(llm: T): T {
  const profileId = typeof llm.profileId === 'string' ? llm.profileId.trim() : '';
  if (profileId.length === 0) {
    return llm;
  }
  return {
    ...llm,
    provider: undefined,
    model: undefined,
    openaiApiMode: undefined,
    baseUrl: undefined,
    apiVersion: undefined,
    timeout: undefined,
    temperature: undefined,
    topP: undefined,
    topK: undefined,
    maxInputTokens: undefined,
    maxOutputTokens: undefined,
    reasoningEffort: undefined,
    reasoningSummary: undefined,
    promptCacheRetention: undefined,
    promptCacheKey: undefined,
    inputCostPerToken: undefined,
    outputCostPerToken: undefined,
  };
}

export function validateAgentSettings(data: unknown, options: { readonly persisted?: boolean } = {}): AgentSettings {
  let payload = applySettingsVersion(data, AGENT_SETTINGS_SCHEMA_VERSION, 'AgentSettings');
  const originalVersion = isRecord(data) ? data.schema_version : undefined;
  const legacy = typeof originalVersion === 'number' ? originalVersion < 8 : options.persisted === true;
  if (legacy && (payload.agent_kind ?? 'openhands') !== 'acp') payload = foldRetiredToolSwitches(payload);
  const legacyAcpLlm = typeof originalVersion === 'number' ? originalVersion < 7 : options.persisted === true;
  if (payload.agent_kind === 'acp' && legacyAcpLlm) delete payload.llm;
  const kind = payload.agent_kind ?? 'openhands';
  if (kind === 'acp') {
    return acpAgentSettingsSchema.parse(payload);
  }
  if (kind === 'llm' || kind === 'openhands') {
    return openHandsAgentSettingsSchema.parse({ ...payload, agent_kind: 'openhands' });
  }
  const renderedKind = typeof kind === 'string' ? kind : JSON.stringify(kind);
  throw new Error(`Unknown agent_kind: ${renderedKind ?? '<unserializable>'}`);
}

export function validateConversationSettings(data: unknown): ConversationSettings {
  return conversationSettingsSchema.parse(
    applySettingsVersion(data, CONVERSATION_SETTINGS_SCHEMA_VERSION, 'ConversationSettings'),
  );
}

export function defaultAgentSettings(llmProfileRef: string): OpenHandsAgentSettings {
  return openHandsAgentSettingsSchema.parse({ llm_profile_ref: llmProfileRef });
}

function applySettingsVersion(data: unknown, currentVersion: number, payloadName: string): Record<string, unknown> {
  if (!isRecord(data)) {
    throw new TypeError(`${payloadName} payload must be a mapping.`);
  }
  const migrated = { ...data };
  const version = migrated.schema_version;
  if (version === undefined || version === null) {
    migrated.schema_version = currentVersion;
    return migrated;
  }
  if (typeof version !== 'number' || !Number.isInteger(version)) {
    throw new TypeError(`${payloadName} schema_version must be an integer, got ${typeof version}.`);
  }
  if (version < 0) {
    throw new Error(`${payloadName} schema_version must be non-negative.`);
  }
  if (version > currentVersion) {
    throw new Error(`${payloadName} schema_version ${version} is newer than supported version ${currentVersion}.`);
  }
  migrated.schema_version = currentVersion;
  return migrated;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}
